namespace sarif.export.trees;




using ghidra.program.model.data.ISF;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.program.model.listing;

public class ExtModule : IsfObject {

	string name;
	string value;

	List<ExtModule> modules = new();
	List<ExtFragment> fragments = new();

	public ExtModule(string name, ProgramModule m, List<object> visited) {
		this.name = name;
		if (!visited.contains(m)) {
			visited.add(m);
			Group[] children = m.getChildren();
			foreach (Group child in children) {
				if (child is ProgramModule cm) {
					ExtModule module = new ExtModule(child.getName(), cm, visited);
					modules.add(module);
				} else if (child is ProgramFragment cf) {
					ExtFragment fragment = new ExtFragment(cf, visited);
					fragments.add(fragment);
				}
			}
		}
	}

}
